"""Renders a ProtocolSpec into a standalone Python connector module.

Each generated module exposes a single `parse(...)` function and depends
only on canonical.py and the stdlib — it has no runtime dependency on the
generator or on PyYAML, so it can be committed and shipped independently of
the tool that produced it.
"""

from __future__ import annotations

from generator.spec import CHECKSUM_ALGOS, FRAMED_BINARY_FIELD_WIDTHS, FieldSpec, ProtocolSpec

_HEADER = '''\
"""Generated connector for {protocol} / {message_id} — DO NOT EDIT BY HAND.

Generated by generator.codegen from a declarative ProtocolSpec.
Regenerate with: python -m generator.cli generate --spec <spec.yaml> --out <this file>
"""

from __future__ import annotations

'''


def generate(spec: ProtocolSpec) -> str:
    if spec.transport == "delimited_text":
        return _generate_delimited_text(spec)
    if spec.transport == "register_map":
        return _generate_register_map(spec)
    if spec.transport == "framed_binary":
        return _generate_framed_binary(spec)
    raise ValueError(f"no codegen backend for transport {spec.transport!r}")


# ---------------------------------------------------------------------------
# delimited_text backend (e.g. ASCII sensor telemetry sentences)
# ---------------------------------------------------------------------------

def _generate_delimited_text(spec: ProtocolSpec) -> str:
    max_index = max(f.index for f in spec.fields)

    ts_field = (
        spec.field_by_name(spec.canonical.timestamp_field)
        if spec.canonical.timestamp_field
        else None
    )
    needs_reference_date = bool(
        ts_field and ts_field.type == "hms_time" and not spec.canonical.date_field
    )

    used_helpers = {"_checksum_ok"}
    if ts_field and ts_field.type == "hms_time":
        used_helpers.add("_ddmmyy_hms_to_iso" if spec.canonical.date_field else "_hms_time_to_iso")
    if spec.canonical.location:
        used_helpers.add("_dm_coord_to_decimal")

    lines: list[str] = []
    lines.append(_HEADER.format(protocol=spec.protocol, message_id=spec.message.id))
    lines.append("import datetime as _dt\n")
    lines.append("from canonical import CanonicalReading, Location, Measurement\n\n")
    lines.append(f'PROTOCOL = "{spec.protocol}"')
    lines.append(f'MESSAGE_TYPE = "{spec.message.id}"')
    lines.append(f'MATCH_SUFFIX = "{spec.message.match_suffix}"')
    lines.append("")
    _emit_helpers(lines, _DELIMITED_TEXT_HELPERS, used_helpers)

    lines.append("def parse(")
    lines.append("    sentence: str,")
    lines.append("    device_id: str,")
    if needs_reference_date:
        lines.append("    reference_date: _dt.date | None = None,")
    lines.append(") -> CanonicalReading | None:")
    lines.append(f'    """Parse one {spec.message.id} sentence into a CanonicalReading."""')
    lines.append("    sentence = sentence.strip()")
    lines.append("    if not _checksum_ok(sentence):")
    lines.append("        return None")
    lines.append("")
    lines.append(f'    parts = sentence.split("*")[0].split("{spec.delimiter}")')
    lines.append(f"    if len(parts) < {max_index + 1}:")
    lines.append("        return None")
    lines.append(
        "    if len(parts[0]) < len(MATCH_SUFFIX) or parts[0][-len(MATCH_SUFFIX):] != MATCH_SUFFIX:"
    )
    lines.append("        return None")
    lines.append("")

    special_types = {"hms_time", "ddmmyy_date", "dm_lat", "dm_lon"}
    for f in spec.fields:
        lines.append("    " + _field_extraction_line(f))

    lines.append("")
    if needs_reference_date:
        lines.append("    reference_date = reference_date or _dt.datetime.now(_dt.timezone.utc).date()")
        lines.append("")

    if ts_field:
        if ts_field.type == "hms_time":
            if spec.canonical.date_field:
                date_field = spec.field_by_name(spec.canonical.date_field)
                lines.append(
                    f"    timestamp = _ddmmyy_hms_to_iso({date_field.name}_raw, {ts_field.name}_raw)"
                )
            else:
                lines.append(f"    timestamp = _hms_time_to_iso({ts_field.name}_raw, reference_date)")
        else:
            lines.append(f"    timestamp = str({ts_field.name})")
    else:
        lines.append('    timestamp = _dt.datetime.now(_dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")')

    if spec.canonical.location:
        loc = spec.canonical.location
        lat_field = spec.field_by_name(loc.lat_field)
        lon_field = spec.field_by_name(loc.lon_field)
        lines.append(
            f"    lat = _dm_coord_to_decimal({lat_field.name}_raw, {loc.lat_dir_field}, degree_digits=2)"
        )
        lines.append(
            f"    lon = _dm_coord_to_decimal({lon_field.name}_raw, {loc.lon_dir_field}, degree_digits=3)"
        )
        lines.append("    location = Location(lat=lat, lon=lon)")
    else:
        lines.append("    location = None")

    lines.append("")
    lines.append("    measurements = [")
    for m in spec.canonical.measurements:
        unit_repr = f'"{m.unit}"' if m.unit else "None"
        lines.append(f'        Measurement(name="{m.name}", value={m.field}, unit={unit_repr}),')
    lines.append("    ]")
    lines.append("")

    lines.append("    raw = {")
    for f in spec.fields:
        var = f"{f.name}_raw" if f.type in special_types else f.name
        lines.append(f'        "{f.name}": {var},')
    lines.append("    }")
    lines.append("")

    lines.append("    return CanonicalReading(")
    lines.append("        device_id=device_id,")
    lines.append("        protocol=PROTOCOL,")
    lines.append("        message_type=MESSAGE_TYPE,")
    lines.append("        timestamp=timestamp,")
    lines.append("        measurements=measurements,")
    lines.append("        location=location,")
    lines.append("        raw=raw,")
    lines.append("    )")
    lines.append("")

    return "\n".join(lines)


def _field_extraction_line(f: FieldSpec) -> str:
    idx = f.index
    if f.type == "str":
        return f"{f.name} = parts[{idx}]"
    if f.type == "int":
        return f"{f.name} = int(parts[{idx}]) if parts[{idx}] else None"
    if f.type == "float":
        return f"{f.name} = float(parts[{idx}]) if parts[{idx}] else None"
    if f.type in ("hms_time", "ddmmyy_date", "dm_lat", "dm_lon"):
        return f"{f.name}_raw = parts[{idx}]"
    raise ValueError(f"unhandled delimited_text field type {f.type!r}")


_DELIMITED_TEXT_HELPERS = '''\
def _checksum_ok(sentence: str) -> bool:
    if "*" not in sentence:
        return False
    body, _, checksum = sentence.partition("*")
    body = body.lstrip("$")
    calc = 0
    for ch in body:
        calc ^= ord(ch)
    try:
        return calc == int(checksum.strip(), 16)
    except ValueError:
        return False


def _hms_time_to_iso(raw: str, reference_date: _dt.date) -> str:
    raw = raw.split(".")[0]
    hh, mm, ss = int(raw[0:2]), int(raw[2:4]), int(raw[4:6])
    dt = _dt.datetime(
        reference_date.year, reference_date.month, reference_date.day,
        hh, mm, ss, tzinfo=_dt.timezone.utc,
    )
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")


def _ddmmyy_hms_to_iso(date_raw: str, time_raw: str) -> str:
    # ddmmyy dates use a 2-digit year; assumed 2000-2099. This is a known
    # limitation of that date encoding itself, not this parser.
    dd, mm, yy = int(date_raw[0:2]), int(date_raw[2:4]), int(date_raw[4:6])
    time_raw = time_raw.split(".")[0]
    hh, mi, ss = int(time_raw[0:2]), int(time_raw[2:4]), int(time_raw[4:6])
    dt = _dt.datetime(2000 + yy, mm, dd, hh, mi, ss, tzinfo=_dt.timezone.utc)
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")


def _dm_coord_to_decimal(raw: str, direction: str, degree_digits: int) -> float:
    degrees = int(raw[:degree_digits])
    minutes = float(raw[degree_digits:])
    decimal = degrees + minutes / 60.0
    if direction in ("S", "W"):
        decimal = -decimal
    return decimal


'''


# ---------------------------------------------------------------------------
# register_map backend (e.g. Modbus)
# ---------------------------------------------------------------------------

_REGISTER_DECODERS = {
    "uint16": "_decode_uint16",
    "int16": "_decode_int16",
    "uint32": "_decode_uint32",
    "int32": "_decode_int32",
}

_REGISTER_HELPERS = '''\
def _decode_uint16(raw: int) -> int:
    return raw & 0xFFFF


def _decode_int16(raw: int) -> int:
    raw &= 0xFFFF
    return raw - 0x10000 if raw & 0x8000 else raw


def _decode_uint32(lo_raw: int, hi_raw: int) -> int:
    # Assumes low word at `address`, high word at `address + 1`.
    return ((hi_raw & 0xFFFF) << 16) | (lo_raw & 0xFFFF)


def _decode_int32(lo_raw: int, hi_raw: int) -> int:
    value = _decode_uint32(lo_raw, hi_raw)
    return value - 0x100000000 if value & 0x80000000 else value


'''


def _generate_register_map(spec: ProtocolSpec) -> str:
    lines: list[str] = []
    lines.append(_HEADER.format(protocol=spec.protocol, message_id=spec.message.id))
    lines.append("from canonical import CanonicalReading, Measurement\n\n")
    lines.append(f'PROTOCOL = "{spec.protocol}"')
    lines.append(f'MESSAGE_TYPE = "{spec.message.id}"')
    lines.append("")

    used_decoders = {_REGISTER_DECODERS[f.type] for f in spec.fields}
    _emit_helpers(lines, _REGISTER_HELPERS, used_decoders)

    lines.append("def parse(")
    lines.append("    registers: dict[int, int],")
    lines.append("    device_id: str,")
    lines.append("    timestamp: str,")
    lines.append(") -> CanonicalReading | None:")
    lines.append(f'    """Parse {spec.message.id} holding registers into a CanonicalReading."""')
    lines.append("    try:")
    for f in spec.fields:
        if f.type in ("uint32", "int32"):
            lines.append(f"        {f.name}_raw = (registers[{f.address}], registers[{f.address + 1}])")
        else:
            lines.append(f"        {f.name}_raw = registers[{f.address}]")
    lines.append("    except KeyError:")
    lines.append("        return None")
    lines.append("")

    for f in spec.fields:
        decoder = _REGISTER_DECODERS[f.type]
        if f.type in ("uint32", "int32"):
            decoded = f"{decoder}(*{f.name}_raw)"
        else:
            decoded = f"{decoder}({f.name}_raw)"
        if f.scale != 1.0:
            lines.append(f"    {f.name} = {decoded} * {f.scale}")
        else:
            lines.append(f"    {f.name} = {decoded}")

    lines.append("")
    lines.append("    measurements = [")
    for m in spec.canonical.measurements:
        unit_repr = f'"{m.unit}"' if m.unit else "None"
        lines.append(f'        Measurement(name="{m.name}", value={m.field}, unit={unit_repr}),')
    lines.append("    ]")
    lines.append("")

    lines.append("    raw = {")
    for f in spec.fields:
        lines.append(f'        "{f.name}": {f.name}_raw,')
    lines.append("    }")
    lines.append("")

    lines.append("    return CanonicalReading(")
    lines.append("        device_id=device_id,")
    lines.append("        protocol=PROTOCOL,")
    lines.append("        message_type=MESSAGE_TYPE,")
    lines.append("        timestamp=timestamp,")
    lines.append("        measurements=measurements,")
    lines.append("        location=None,")
    lines.append("        raw=raw,")
    lines.append("    )")
    lines.append("")

    return "\n".join(lines)


def _split_helpers(block: str) -> list[tuple[str, str]]:
    """Split a block of top-level function defs into (name, source) pairs.

    Each source is rstripped so callers can join a chosen subset with
    consistent spacing regardless of which helpers were filtered out.
    """
    chunks: list[tuple[str, str]] = []
    current: list[str] = []
    current_name: str | None = None
    for line in block.splitlines(keepends=True):
        if line.startswith("def "):
            if current_name is not None:
                chunks.append((current_name, "".join(current).rstrip("\n")))
            current_name = line[len("def "):].split("(")[0]
            current = [line]
        else:
            current.append(line)
    if current_name is not None:
        chunks.append((current_name, "".join(current).rstrip("\n")))
    return chunks


def _emit_helpers(lines: list[str], block: str, wanted: set[str]) -> None:
    """Append the chunks of `block` whose name is in `wanted`, evenly spaced."""
    selected = [src for name, src in _split_helpers(block) if name in wanted]
    if selected:
        lines.append("\n\n\n".join(selected))
        lines.append("")


# ---------------------------------------------------------------------------
# framed_binary backend (optional sync + length/fixed size + optional type byte +
# payload + checksum + optional constant trailer)
# ---------------------------------------------------------------------------

_STRUCT_FORMATS = {
    "uint8": "B", "int8": "b",
    "uint16_be": ">H", "uint16_le": "<H", "int16_be": ">h", "int16_le": "<h",
    "uint32_be": ">I", "uint32_le": "<I", "int32_be": ">i", "int32_le": "<i",
}

_CHECKSUM_FUNCS = {
    ("crc8", True): """\
def _checksum(data: bytes) -> int:
    crc = CHK_INIT
    for b in data:
        crc ^= b
        for _ in range(8):
            crc = (crc >> 1) ^ CHK_POLY if crc & 1 else crc >> 1
    return crc ^ CHK_XOROUT
""",
    ("crc8", False): """\
def _checksum(data: bytes) -> int:
    crc = CHK_INIT
    for b in data:
        crc ^= b
        for _ in range(8):
            crc = ((crc << 1) ^ CHK_POLY) & 0xFF if crc & 0x80 else (crc << 1) & 0xFF
    return crc ^ CHK_XOROUT
""",
    ("crc32", True): """\
def _checksum(data: bytes) -> int:
    crc = CHK_INIT
    for b in data:
        crc ^= b
        for _ in range(8):
            crc = (crc >> 1) ^ CHK_POLY if crc & 1 else crc >> 1
    return (crc ^ CHK_XOROUT) & 0xFFFFFFFF
""",
    ("crc32", False): """\
def _checksum(data: bytes) -> int:
    crc = CHK_INIT
    for b in data:
        crc ^= b << 24
        for _ in range(8):
            crc = ((crc << 1) ^ CHK_POLY) & 0xFFFFFFFF if crc & 0x80000000 else (crc << 1) & 0xFFFFFFFF
    return (crc ^ CHK_XOROUT) & 0xFFFFFFFF
""",
    ("crc16", True): """\
def _checksum(data: bytes) -> int:
    crc = CHK_INIT
    for b in data:
        crc ^= b
        for _ in range(8):
            crc = (crc >> 1) ^ CHK_POLY if crc & 1 else crc >> 1
    return crc ^ CHK_XOROUT
""",
    ("crc16", False): """\
def _checksum(data: bytes) -> int:
    crc = CHK_INIT
    for b in data:
        crc ^= b << 8
        for _ in range(8):
            crc = ((crc << 1) ^ CHK_POLY) & 0xFFFF if crc & 0x8000 else (crc << 1) & 0xFFFF
    return crc ^ CHK_XOROUT
""",
    ("fletcher8", False): """\
def _checksum(data: bytes) -> int:
    s1 = s2 = 0
    for b in data:
        s1 = (s1 + b) % 255
        s2 = (s2 + s1) % 255
    return (s2 << 8) | s1
""",
    ("fletcher8_256", False): """\
def _checksum(data: bytes) -> int:
    s1 = s2 = 0
    for b in data:
        s1 = (s1 + b) & 0xFF
        s2 = (s2 + s1) & 0xFF
    return (s2 << 8) | s1
""",
    ("sum16", False): """\
def _checksum(data: bytes) -> int:
    return ((CHK_INIT + sum(data)) & 0xFFFF) ^ CHK_XOROUT
""",
    ("negsum8", False): """\
def _checksum(data: bytes) -> int:
    return (CHK_INIT - sum(data)) & 0xFF
""",
    ("negsum16", False): """\
def _checksum(data: bytes) -> int:
    return (CHK_INIT - sum(data)) & 0xFFFF
""",
    ("sum8", False): """\
def _checksum(data: bytes) -> int:
    return ((CHK_INIT + sum(data)) & 0xFF) ^ CHK_XOROUT
""",
    ("xor8", False): """\
def _checksum(data: bytes) -> int:
    acc = CHK_INIT
    for b in data:
        acc ^= b
    return acc ^ CHK_XOROUT
""",
}


def _reflect16(value: int) -> int:
    return int(f"{value & 0xFFFF:016b}"[::-1], 2)


def _reflect(value: int, width: int) -> int:
    return int(f"{value & ((1 << width) - 1):0{width}b}"[::-1], 2)


def _generate_framed_binary(spec: ProtocolSpec) -> str:
    fr = spec.framing
    crc = fr.crc
    sync = bytes.fromhex(fr.sync)
    trailer = bytes.fromhex(fr.trailer)
    chk_size = CHECKSUM_ALGOS[crc.algo] if crc else 0
    length_based = fr.length_offset is not None
    min_frame = fr.payload_offset + chk_size + len(trailer)

    L: list[str] = []
    L.append(_HEADER.format(protocol=spec.protocol, message_id=spec.message.id))
    L.append("import struct\n")
    L.append("from typing import Iterator\n")
    L.append("from canonical import CanonicalReading, Measurement\n\n")
    L.append(f'PROTOCOL = "{spec.protocol}"')
    L.append(f'MESSAGE_TYPE = "{spec.message.id}"')
    L.append("")
    L.append(f'SYNC = bytes.fromhex("{fr.sync}")')
    if length_based:
        L.append(f"LENGTH_OFFSET = {fr.length_offset}")
        L.append(f"LENGTH_OVERHEAD = {fr.length_overhead}")
    else:
        L.append(f"FRAME_LENGTH = {fr.fixed_length}")
    if fr.type_offset is not None:
        L.append(f"TYPE_OFFSET = {fr.type_offset}")
        L.append(f"TYPE_VALUE = {spec.message.type_value:#04x}")
    L.append(f"PAYLOAD_OFFSET = {fr.payload_offset}")
    if spec.message.payload_length is not None:
        L.append(f"PAYLOAD_LENGTH = {spec.message.payload_length}")
    L.append(f'TRAILER = bytes.fromhex("{fr.trailer}")')
    L.append(f"MIN_FRAME = {min_frame}")
    L.append(f"CHK_SIZE = {chk_size}")
    if crc:
        L.append(f"CHK_START = {crc.start}")
        if crc.algo in ("crc8", "crc16", "crc32"):
            width = {"crc8": 8, "crc16": 16, "crc32": 32}[crc.algo]
            poly = _reflect(crc.poly, width) if crc.reflected else crc.poly
            L.append(f"CHK_POLY = {poly:#0{2 + width // 4}x}")
        if crc.algo in ("crc8", "crc16", "crc32", "sum8", "sum16", "negsum8", "negsum16", "xor8"):
            L.append(f"CHK_INIT = {crc.init:#06x}")
            L.append(f"CHK_XOROUT = {crc.xorout:#06x}")
        if chk_size > 1:
            L.append(f'CHK_BYTEORDER = "{crc.endian}"')
    L.append("")
    L.append("")

    if crc:
        L.append(_CHECKSUM_FUNCS[(crc.algo, crc.reflected if crc.algo in ("crc8", "crc16", "crc32") else False)].rstrip("\n"))
        L.append("")
        L.append("")
    L.append("def _frame_ok(frame: bytes) -> bool:")
    L.append("    if len(frame) < MIN_FRAME:")
    L.append("        return False")
    if trailer:
        L.append("    if not frame.endswith(TRAILER):")
        L.append("        return False")
    if crc:
        L.append("    end = len(frame) - len(TRAILER) - CHK_SIZE")
        byteorder = "CHK_BYTEORDER" if chk_size > 1 else '"big"'
        L.append(f"    stored = int.from_bytes(frame[end:end + CHK_SIZE], {byteorder})")
        L.append("    return _checksum(frame[CHK_START:end]) == stored")
    else:
        L.append("    return True")
    L.append("")
    L.append("")
    L.append("def iter_frames(stream: bytes) -> Iterator[bytes]:")
    L.append('    """Yield every well-formed frame (any message type) found in a byte stream.')
    L.append("")
    L.append("    Resynchronises after line noise or a corrupt frame: a candidate whose length,")
    L.append("    trailer or check value does not hold up is skipped one byte at a time,")
    L.append('    looking for the sync bytes again (or, without sync bytes, for the next offset')
    L.append('    where the check value fits).')
    L.append('    """')
    L.append("    i, n = 0, len(stream)")
    L.append("    while i < n:")
    if sync:
        L.append("        i = stream.find(SYNC, i)")
        L.append("        if i < 0:")
        L.append("            return")
    if length_based:
        L.append("        if i + LENGTH_OFFSET >= n:")
        L.append("            return")
        L.append("        end = i + stream[i + LENGTH_OFFSET] + LENGTH_OVERHEAD")
    else:
        L.append("        end = i + FRAME_LENGTH")
    L.append("        if end <= n and _frame_ok(stream[i:end]):")
    L.append("            yield stream[i:end]")
    L.append("            i = end")
    L.append("        else:")
    L.append("            i += 1")
    L.append("")
    L.append("")
    L.append("def parse(")
    L.append("    frame: bytes,")
    L.append("    device_id: str,")
    L.append("    timestamp: str,")
    L.append(") -> CanonicalReading | None:")
    L.append(f'    """Parse one {spec.message.id} frame into a CanonicalReading.')
    L.append("")
    L.append("    Returns None for frames of another message type or that fail the length /")
    L.append("    trailer / check-value tests. The wire has no clock, so the caller supplies")
    L.append('    the timestamp.')
    L.append('    """')
    L.append("    if len(frame) < MIN_FRAME:")
    L.append("        return None")
    if sync:
        L.append("    if frame[: len(SYNC)] != SYNC:")
        L.append("        return None")
    if length_based:
        L.append("    if len(frame) != frame[LENGTH_OFFSET] + LENGTH_OVERHEAD:")
    else:
        L.append("    if len(frame) != FRAME_LENGTH:")
    L.append("        return None")
    L.append("    if not _frame_ok(frame):")
    L.append("        return None")
    if fr.type_offset is not None:
        L.append("    if frame[TYPE_OFFSET] != TYPE_VALUE:")
        L.append("        return None")
    L.append("    payload = frame[PAYLOAD_OFFSET:len(frame) - len(TRAILER) - CHK_SIZE]")
    if spec.message.payload_length is not None:
        L.append("    if len(payload) != PAYLOAD_LENGTH:")
    else:
        need = max(f.offset + FRAMED_BINARY_FIELD_WIDTHS[f.type] for f in spec.fields)
        L.append(f"    if len(payload) < {need}:")
    L.append("        return None")
    L.append("")
    for f in spec.fields:
        L.append(f'    {f.name}_raw = struct.unpack_from("{_STRUCT_FORMATS[f.type]}", payload, {f.offset})[0]')
    L.append("")
    for f in spec.fields:
        expr = f"{f.name}_raw"
        if f.scale != 1.0:
            expr += f" * {f.scale!r}"
        if f.bias:
            expr += f" + {f.bias!r}"
        L.append(f"    {f.name} = {expr}")
    L.append("")
    L.append("    measurements = [")
    for m in spec.canonical.measurements:
        unit_repr = f'"{m.unit}"' if m.unit else "None"
        L.append(f'        Measurement(name="{m.name}", value={m.field}, unit={unit_repr}),')
    L.append("    ]")
    L.append("")
    L.append("    raw = {")
    for f in spec.fields:
        L.append(f'        "{f.name}": {f.name}_raw,')
    L.append("    }")
    L.append("")
    L.append("    return CanonicalReading(")
    L.append("        device_id=device_id,")
    L.append("        protocol=PROTOCOL,")
    L.append("        message_type=MESSAGE_TYPE,")
    L.append("        timestamp=timestamp,")
    L.append("        measurements=measurements,")
    L.append("        location=None,")
    L.append("        raw=raw,")
    L.append("    )")
    L.append("")
    return "\n".join(L)
